(function(){
  'use strict';
  const D=window.CSFLData,Q=window.CSFLQuestions,S=window.CSFLState,K=window.CSFLKQL;
  const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
  const esc=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const fmt=t=>{try{return new Date(t).toLocaleString(undefined,{month:'short',day:'2-digit',hour:'2-digit',minute:'2-digit'});}catch{return t}};
  const sevRank={critical:4,high:3,medium:2,low:1};
  let currentQuiz=null,selectedIdentity=4,selectedZT=4,selectedDetection='failed-logins',lastKqlResult=null,selectedIncident='INC-2401',iacTab='network';
  let idFilter={q:'',risk:'all'},ztFilter={q:'',result:'all',country:'all'};

  function toast(title,msg='',kind=''){
    const el=document.createElement('div'); el.className=`toast ${kind}`; el.innerHTML=`<b>${esc(title)}</b>${msg?`<span>${esc(msg)}</span>`:''}`;
    $('#toastRegion').appendChild(el); setTimeout(()=>el.remove(),3800);
  }
  function modal(title,body,actions=''){
    $('#modal').innerHTML=`<div class="eyebrow">LOCAL ACTION</div><h2 id="modalTitle">${esc(title)}</h2>${body}<div class="modal-actions">${actions||'<button class="btn" data-modal-close>CLOSE</button>'}</div>`;
    $('#modalBackdrop').classList.remove('hidden'); $('#modalBackdrop').setAttribute('aria-hidden','false');
  }
  function closeModal(){ $('#modalBackdrop').classList.add('hidden'); $('#modalBackdrop').setAttribute('aria-hidden','true'); }
  function download(name,text,type='text/plain'){
    const a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;document.body.appendChild(a);a.click();URL.revokeObjectURL(a.href);a.remove();
  }
  function markModule(view){ S.patch(s=>{s.completedModules[view]=true;}); }
  function bumpSkill(name,amount){S.patch(s=>{s.skills[name]=Math.min(100,(s.skills[name]||0)+amount);});}
  function riskBadge(v){return `<span class="badge ${String(v).toLowerCase()}">${esc(String(v).toUpperCase())}</span>`}
  function boolBadge(v){return v?'<span class="badge success">YES</span>':'<span class="badge danger">NO</span>'}

  function navigate(view){
    if(!document.querySelector(`[data-view-panel="${view}"]`)) view='dashboard';
    $$('.view').forEach(v=>v.classList.toggle('active',v.dataset.viewPanel===view));
    $$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));
    S.patch(s=>s.lastView=view); render(view); $('#app').focus({preventScroll:true}); window.scrollTo({top:0,behavior:'smooth'});
  }
  function render(view){
    ({dashboard:renderDashboard,learn:renderLearnHome,identity:renderIdentity,'zero-trust':renderZeroTrust,detections:renderDetections,incidents:renderIncidents,posture:renderPosture,iac:renderIaC,portfolio:renderPortfolio}[view]||renderDashboard)();
  }

  // DASHBOARD
  function renderDashboard(){
    const s=S.get(); const completed=Object.values(s.completedModules).filter(Boolean).length;
    const remediated=s.posture.findings.filter(f=>f.remediated).length;
    const resolved=s.incidents.filter(i=>i.status==='Resolved').length;
    const score=Math.round(Object.values(s.skills).reduce((a,b)=>a+b,0)/Object.keys(s.skills).length);
    $('#dashboardMetrics').innerHTML=[
      ['OVERALL PROGRESS',`${Math.round(completed/8*100)}%`,`${completed}/8 modules touched`,completed/8*100],
      ['SECURITY SKILL SCORE',`${score}`,`Level ${s.level} / ${s.xp} XP`,score],
      ['DETECTION RUNS',`${s.detections.runs.length}`,`${s.detections.saved.length} rules saved`,Math.min(100,s.detections.runs.length*12)],
      ['RESPONSE / POSTURE',`${resolved}/${remediated}`,`${resolved} incidents resolved · ${remediated} findings fixed`,Math.min(100,(resolved+remediated)*15)]
    ].map(m=>`<div class="metric-card"><span class="metric-label">${m[0]}</span><b class="metric-value">${m[1]}</b><span class="metric-sub">${m[2]}</span><div class="metric-progress"><span style="width:${m[3]}%"></span></div></div>`).join('');
    $('#moduleGrid').innerHTML=D.modules.map(m=>`<article class="module-card" data-action="navigate" data-view="${m.view}"><span class="module-index">MODULE // ${m.index}</span><h3>${esc(m.title)}</h3><p>${esc(m.desc)}</p><footer class="module-foot"><span>${s.completedModules[m.view]?'TOUCHED':'READY'}</span><b>${esc(m.tag)} →</b></footer></article>`).join('');
    $('#skillLevelBadge').textContent=`LEVEL ${s.level}`;
    $('#skillMatrix').innerHTML=Object.entries(s.skills).map(([k,v])=>`<div class="skill-row"><span>${esc(k.replace(/([A-Z])/g,' $1').trim())}</span><div class="skill-bar"><i style="width:${v}%"></i></div><b>${v}%</b></div>`).join('');
    $('#recentActions').innerHTML=s.actions.slice(0,7).map(a=>`<div class="activity-item"><time>${fmt(a.time)}</time><div>${esc(a.text)}</div></div>`).join('')||'<div class="micro-copy">No local actions yet.</div>';
    renderTerminal();
  }
  function renderTerminal(){
    const lines=['[ok] local telemetry mounted','[ok] identity dataset: 8 assignments','[ok] SigninLogs: 15 baseline events','[ok] detection catalog: 8 rules','[ok] KQL runtime ready','[hot] synthetic attack chain seeded','[ok] no cloud deployment required'];
    $('#systemTerminal').innerHTML=lines.map((x,i)=>`<div class="${x.includes('[hot]')?'hot':'ok'}">${esc(x)}</div>`).join('');
  }

  // LEARN
  function certMeta(cert){
    const rows=Q[cert],domains=[...new Set(rows.map(q=>q.domain))]; const hist=S.get().quiz[cert].history; const last=hist[0];
    return {count:rows.length,domains,last};
  }
  function renderLearnHome(){
    $('#quizWorkspace').classList.add('hidden');$('#learnHome').classList.remove('hidden'); $('#learnDrawer').classList.add('hidden'); currentQuiz=null;
    $('#learnHome').innerHTML=`<div class="cert-grid">${['AZ-900','SC-900'].map(cert=>{const m=certMeta(cert);return `<article class="cert-card"><div class="cert-code">${cert} // ORIGINAL TRAINING BANK</div><h2>${cert}</h2><p>${cert==='AZ-900'?'Azure cloud concepts, architecture, governance, networking, management and security fundamentals.':'Security, compliance, identity, Microsoft Entra, Defender, Sentinel and Purview fundamentals.'}</p><div class="stat-strip" style="margin-top:18px"><div class="stat-box"><span>QUESTIONS</span><b>${m.count}</b><small>Original project content</small></div><div class="stat-box"><span>DOMAINS</span><b>${m.domains.length}</b><small>Domain tracking</small></div><div class="stat-box"><span>LAST SCORE</span><b>${m.last?m.last.score+'%':'—'}</b><small>${m.last?fmt(m.last.date):'No session yet'}</small></div><div class="stat-box"><span>TARGET</span><b>80%</b><small>Local training target</small></div></div><div class="mode-row">${[['quick','Quick Practice','10 questions'],['study','Study Session','20 questions'],['full','Full Block','50 questions'],['exam','Exam Mode','50 · feedback at end']].map(x=>`<button class="mode-btn" data-quiz-start="${cert}" data-mode="${x[0]}"><b>${x[1]}</b><span>${x[2]}</span></button>`).join('')}</div></article>`}).join('')}</div>
    <div class="card"><div class="card-title"><div><div class="eyebrow">ROLE-BASED LEARNING</div><h2>Security Capability Tracks</h2></div></div><div class="module-grid">${[['Cloud Ops','Azure hierarchy, networking, governance and monitoring.','Azure'],['Identity','Entra ID, roles, MFA, Conditional Access and access reviews.','Identity'],['Detection','KQL, analytic thinking, MITRE mapping and rule design.','Detection'],['Response','Triage, containment, evidence and incident documentation.','IncidentResponse']].map((x,i)=>`<article class="module-card" data-action="navigate" data-view="${i===0?'iac':i===1?'identity':i===2?'detections':'incidents'}"><span class="module-index">TRACK // 0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p><footer class="module-foot"><span>${S.get().skills[x[2]]||0}% CURRENT</span><b>OPEN →</b></footer></article>`).join('')}</div></div>`;
    markModule('learn');
  }
  function startQuiz(cert,mode){
    const all=[...Q[cert]]; const size=mode==='quick'?10:mode==='study'?20:50;
    let pool=all;
    if(mode==='quick'||mode==='study') pool=shuffle(all).slice(0,size); else pool=all.slice(0,size);
    currentQuiz={cert,mode,questions:pool,index:0,answers:[],locked:false,exam:mode==='exam',started:new Date().toISOString()};
    $('#learnHome').classList.add('hidden');$('#learnDrawer').classList.add('hidden');$('#quizWorkspace').classList.remove('hidden');renderQuizQuestion();
  }
  function shuffle(a){return a.map(v=>[Math.random(),v]).sort((x,y)=>x[0]-y[0]).map(x=>x[1]);}
  function renderQuizQuestion(){
    const q=currentQuiz.questions[currentQuiz.index],answered=currentQuiz.answers[currentQuiz.index]; const progress=(currentQuiz.index/currentQuiz.questions.length)*100;
    const correctSoFar=currentQuiz.answers.filter(a=>a&&a.correct).length;
    $('#quizWorkspace').innerHTML=`<section class="quiz-card"><div class="quiz-meta"><div><span class="badge info">${currentQuiz.cert}</span> <span class="badge purple">${esc(q.domain)}</span></div><span class="micro-copy">QUESTION ${currentQuiz.index+1} / ${currentQuiz.questions.length}</span></div><div class="quiz-progress"><span style="width:${progress}%"></span></div><div class="quiz-question" style="margin-top:22px">${esc(q.question)}</div><div class="answer-list">${q.choices.map((c,i)=>{let cls='';if(answered&&!currentQuiz.exam){cls=i===q.correct?'correct':i===answered.choice&&!answered.correct?'wrong':'';}else if(answered&&i===answered.choice)cls='selected';return `<button class="answer-btn ${cls}" data-answer="${i}" ${answered?'disabled':''}><span class="letter">${String.fromCharCode(65+i)}</span><span>${esc(c)}</span></button>`}).join('')}</div>${answered&&!currentQuiz.exam?`<div class="quiz-explanation"><strong>${answered.correct?'Correct.':'Not quite.'}</strong> ${esc(q.explanation)}</div>`:''}<div class="toolbar" style="justify-content:space-between;margin-top:18px"><button class="btn" data-quiz-exit>EXIT SESSION</button>${answered?`<button class="btn primary" data-quiz-next>${currentQuiz.index===currentQuiz.questions.length-1?'FINISH SESSION':'NEXT QUESTION'}</button>`:''}</div></section><aside class="quiz-side"><div class="eyebrow">LIVE SESSION</div><h2 style="margin:8px 0 18px">${currentQuiz.exam?'Exam Mode':'Practice Mode'}</h2><div class="detail-list"><div class="detail-row"><span>Mode</span><b>${esc(currentQuiz.mode.toUpperCase())}</b></div><div class="detail-row"><span>Answered</span><b>${currentQuiz.answers.filter(Boolean).length}/${currentQuiz.questions.length}</b></div><div class="detail-row"><span>Correct</span><b>${currentQuiz.exam?'Hidden':correctSoFar}</b></div><div class="detail-row"><span>Target</span><b>80% local threshold</b></div></div><div class="callout ${currentQuiz.exam?'amber':''}" style="margin-top:16px">${currentQuiz.exam?'Exam Mode hides correctness and explanations until the end.':'Study and practice modes explain each answer immediately.'}</div></aside>`;
  }
  function answerQuiz(choice){
    if(!currentQuiz||currentQuiz.answers[currentQuiz.index]) return; const q=currentQuiz.questions[currentQuiz.index]; currentQuiz.answers[currentQuiz.index]={choice,correct:choice===q.correct}; renderQuizQuestion();
  }
  function nextQuiz(){ if(currentQuiz.index>=currentQuiz.questions.length-1) return finishQuiz(); currentQuiz.index++; renderQuizQuestion(); }
  function finishQuiz(){
    const correct=currentQuiz.answers.filter(a=>a&&a.correct).length, total=currentQuiz.questions.length, score=Math.round(correct/total*100);
    const wrong=currentQuiz.questions.filter((q,i)=>!currentQuiz.answers[i]?.correct);
    S.patch(s=>{const qstate=s.quiz[currentQuiz.cert];qstate.history.unshift({date:new Date().toISOString(),mode:currentQuiz.mode,score,correct,total});qstate.history=qstate.history.slice(0,20);wrong.forEach(q=>qstate.wrongByDomain[q.domain]=(qstate.wrongByDomain[q.domain]||0)+1);});
    S.addXP(Math.max(10,correct*2),`${currentQuiz.cert} ${currentQuiz.mode} session completed`); bumpSkill('Azure',currentQuiz.cert==='AZ-900'?2:0);bumpSkill('Identity',currentQuiz.cert==='SC-900'?2:0); markModule('learn');
    $('#quizWorkspace').innerHTML=`<section class="quiz-card" style="grid-column:1/-1"><div class="eyebrow">SESSION COMPLETE</div><h2 style="font-size:38px;margin:10px 0">${score}%</h2><p>${correct} of ${total} correct. ${score>=80?'Local training target reached.':'Use the weak-area view to focus the next review.'}</p><div class="stat-strip"><div class="stat-box"><span>CORRECT</span><b>${correct}</b><small>of ${total}</small></div><div class="stat-box"><span>WRONG</span><b>${total-correct}</b><small>reviewable</small></div><div class="stat-box"><span>THRESHOLD</span><b>${score>=80?'PASS':'REVIEW'}</b><small>project target</small></div><div class="stat-box"><span>XP</span><b>+${Math.max(10,correct*2)}</b><small>local progress</small></div></div>${wrong.length?`<div class="card" style="margin-top:12px"><div class="card-title"><h3>Review missed topics</h3></div>${wrong.slice(0,8).map(q=>`<div class="callout" style="margin-top:8px"><strong>${esc(q.domain)}</strong><br>${esc(q.question)}<br><span style="color:#818188">${esc(q.explanation)}</span></div>`).join('')}</div>`:''}<div class="toolbar"><button class="btn primary" data-quiz-home>BACK TO TRAINING HUB</button></div></section>`;
    currentQuiz=null;
  }
  function showLearnDrawer(type){
    const el=$('#learnDrawer');el.classList.remove('hidden');
    if(type==='history') el.innerHTML=`<div class="card-title"><div><div class="eyebrow">TRAINING HISTORY</div><h2>Recent sessions</h2></div><button class="btn small" data-drawer-close>CLOSE</button></div>${['AZ-900','SC-900'].map(cert=>`<h3>${cert}</h3><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Date</th><th>Mode</th><th>Score</th><th>Correct</th></tr></thead><tbody>${S.get().quiz[cert].history.map(h=>`<tr><td>${fmt(h.date)}</td><td>${h.mode}</td><td>${h.score}%</td><td>${h.correct}/${h.total}</td></tr>`).join('')||'<tr><td colspan="4">No sessions yet.</td></tr>'}</tbody></table></div>`).join('')}`;
    else el.innerHTML=`<div class="card-title"><div><div class="eyebrow">WEAK AREA TRACKING</div><h2>Domains with missed questions</h2></div><button class="btn small" data-drawer-close>CLOSE</button></div>${['AZ-900','SC-900'].map(cert=>{const entries=Object.entries(S.get().quiz[cert].wrongByDomain).sort((a,b)=>b[1]-a[1]);return `<h3>${cert}</h3><div class="domain-list">${entries.map(([d,n])=>`<div class="domain-row"><b>${esc(d)}</b><span>${n} misses</span></div>`).join('')||'<div class="micro-copy">No weak areas recorded yet.</div>'}</div>`}).join('')}`;
    el.scrollIntoView({behavior:'smooth',block:'start'});
  }

  // IDENTITY
  function identityEffective(row,index){
    const r={...row}; const acts=S.get().identity.remediations.filter(x=>x.index===index);
    acts.forEach(a=>{if(a.type==='remove')r.Removed=true;if(a.type==='mfa')r.MFAEnabled=true;if(a.type==='eligible')r.AccessType='Eligible / JIT';}); return r;
  }
  function identityRisk(r){
    if(r.Removed) return 'low'; let n=0;if(r.Privileged)n+=2;if(!r.ExpectedAccess)n+=3;if(!r.MFAEnabled)n+=2;if(r.Scope==='Subscription'||r.Scope==='Tenant')n+=1;if(r.AccessType==='Permanent'&&r.Privileged)n+=1;
    return n>=7?'critical':n>=5?'high':n>=3?'medium':'low';
  }
  function renderIdentity(){
    const rows=D.roleAssignments.map(identityEffective); const visible=rows.map((r,i)=>({r,i})).filter(x=>(idFilter.risk==='all'||identityRisk(x.r)===idFilter.risk)&&(!idFilter.q||JSON.stringify(x.r).toLowerCase().includes(idFilter.q.toLowerCase())));
    const privileged=rows.filter(r=>r.Privileged&&!r.Removed).length,unexpected=rows.filter(r=>!r.ExpectedAccess&&!r.Removed).length,high=rows.filter(r=>['high','critical'].includes(identityRisk(r))).length;
    const current=rows[selectedIdentity]||rows[0]; const curRisk=identityRisk(current); const tasks=S.get().identity.tasks;
    $('#identityContent').innerHTML=`<div class="stat-strip"><div class="stat-box"><span>TOTAL ASSIGNMENTS</span><b>${rows.length}</b><small>mixed Entra + Azure RBAC</small></div><div class="stat-box"><span>PRIVILEGED</span><b>${privileged}</b><small>active standing privilege</small></div><div class="stat-box"><span>UNEXPECTED</span><b>${unexpected}</b><small>ExpectedAccess = false</small></div><div class="stat-box"><span>HIGH / CRITICAL</span><b>${high}</b><small>derived local risk</small></div></div><div class="workspace-grid"><section class="stack"><div class="card"><div class="card-title"><div><div class="eyebrow">ACCESS GRAPH</div><h2>Role Assignments</h2></div></div><div class="toolbar"><input class="input" id="identitySearch" placeholder="Search user, role, scope..." value="${esc(idFilter.q)}" style="max-width:320px"><select class="input" id="identityRiskFilter" style="max-width:170px"><option value="all">All risk</option>${['critical','high','medium','low'].map(r=>`<option ${idFilter.risk===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>User</th><th>Job role</th><th>Assigned role</th><th>Role system</th><th>Scope</th><th>MFA</th><th>Expected</th><th>Risk</th></tr></thead><tbody>${visible.map(({r,i})=>`<tr class="${i===selectedIdentity?'selected':''}" data-identity-row="${i}"><td><span class="table-link">${esc(r.User)}${r.Removed?' · REMOVED':''}</span></td><td>${esc(r.JobRole)}</td><td>${esc(r.AssignedRole)}</td><td>${esc(r.RoleSystem)}</td><td>${esc(r.Scope)}</td><td>${boolBadge(r.MFAEnabled)}</td><td>${boolBadge(r.ExpectedAccess)}</td><td>${riskBadge(identityRisk(r))}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><div class="card-title"><div><div class="eyebrow">ANALYST WORK</div><h2>Review Tasks & Notes</h2></div></div><div class="check-list">${[['role','Identify whether the assigned role matches the job role.'],['scope','Evaluate whether the scope is broader than necessary.'],['auth','Review MFA and permanent privilege exposure.'],['response','Document a least-privilege response recommendation.']].map(([k,t])=>`<label class="check-row"><input type="checkbox" data-identity-task="${k}" ${tasks[k]?'checked':''}><span>${esc(t)}</span></label>`).join('')}</div><textarea class="input" id="identityNotes" placeholder="Write your analyst finding..." style="margin-top:12px">${esc(S.get().identity.notes)}</textarea><div class="toolbar"><button class="btn primary" id="saveIdentityDecisionBtn">SAVE REVIEW</button><button class="btn" id="revealIdentityFindingBtn">REVEAL EXPECTED FINDING</button></div></div></section><aside class="stack"><div class="card"><div class="card-title"><div><div class="eyebrow">SELECTED PRINCIPAL</div><h2>${esc(current.User)}</h2></div>${riskBadge(curRisk)}</div><div class="detail-list">${[['Job Role',current.JobRole],['Assigned Role',current.AssignedRole],['Role System',current.RoleSystem],['Scope',current.Scope],['Access Type',current.AccessType],['MFA',current.MFAEnabled?'Enabled':'Disabled'],['Expected',current.ExpectedAccess?'Yes':'No']].map(x=>`<div class="detail-row"><span>${x[0]}</span><b>${esc(x[1])}</b></div>`).join('')}</div><div class="toolbar"><button class="btn danger small" data-id-remediate="remove">REMOVE ROLE</button><button class="btn small" data-id-remediate="mfa">REQUIRE MFA</button><button class="btn small" data-id-remediate="eligible">CONVERT TO JIT</button></div></div><div class="card"><div class="eyebrow">RISK LOGIC</div><h3 style="margin:8px 0">Why this matters</h3><div class="callout ${curRisk==='low'?'green':curRisk==='medium'?'amber':''}">${current.Removed?'<strong>Role removed in simulation.</strong> The canonical source data is preserved; local state records the remediation.':`<strong>${esc(current.AssignedRole)}</strong> on <strong>${esc(current.Scope)}</strong> is evaluated together with MFA, expected access and standing privilege. A powerful role is not automatically wrong; context and scope matter.`}</div></div></aside></div>`;
    markModule('identity');
  }
  function saveIdentityReview(){
    const notes=$('#identityNotes')?.value.trim()||''; const tasks=S.get().identity.tasks; const complete=['role','scope','auth','response'].every(k=>tasks[k])&&notes.length>25;
    S.patch(s=>{s.identity.notes=notes;s.identity.completed=complete;}); if(complete){S.addXP(90,'Identity & Access Review completed');bumpSkill('Identity',6);addCase('CASE-IDENTITY','Excessive Privilege Review','Reviewed Entra and Azure RBAC assignments, identified unexpected standing privilege and documented least-privilege remediation.','Identity / IAM');toast('Access review complete','Identity case added to the portfolio casebook.','success');}else toast('Review saved','Complete all four tasks and write a short finding to finish the lab.'); renderIdentity();
  }
  function remediateIdentity(type){const index=selectedIdentity;S.patch(s=>{if(!s.identity.remediations.some(r=>r.index===index&&r.type===type))s.identity.remediations.push({index,type,time:new Date().toISOString()});});S.addAction(`Identity remediation simulated: ${type} on ${D.roleAssignments[index].User}.`);toast('Remediation simulated',`${type} applied to local lab state.`,'success');renderIdentity();}

  // ZERO TRUST
  function ztRows(){return [...D.signins,...S.get().zeroTrust.extraSignals];}
  function renderZeroTrust(){
    let rows=ztRows().slice().sort((a,b)=>new Date(b.TimeGenerated)-new Date(a.TimeGenerated));
    rows=rows.filter(r=>(ztFilter.result==='all'||r.Result.toLowerCase()===ztFilter.result)&&(ztFilter.country==='all'||r.Country===ztFilter.country)&&(!ztFilter.q||JSON.stringify(r).toLowerCase().includes(ztFilter.q.toLowerCase())));
    const all=ztRows();const fail=all.filter(r=>r.ResultType!==0).length,success=all.filter(r=>r.ResultType===0).length,noMfa=all.filter(r=>r.ResultType===0&&!r.MFAUsed).length,high=all.filter(r=>r.RiskLevel==='high').length; const target=all.find(r=>r.SessionId==='S-9005')||all[0];
    const selected=all[selectedZT]||target;const tasks=S.get().zeroTrust.tasks;
    const countries=[...new Set(all.map(r=>r.Country))].sort();
    $('#zeroTrustContent').innerHTML=`<div class="stat-strip"><div class="stat-box"><span>EVENTS</span><b>${all.length}</b><small>synthetic SigninLogs</small></div><div class="stat-box"><span>FAILURES / SUCCESS</span><b>${fail}/${success}</b><small>authentication outcomes</small></div><div class="stat-box"><span>SUCCESS WITHOUT MFA</span><b>${noMfa}</b><small>review required</small></div><div class="stat-box"><span>HIGH RISK</span><b>${high}</b><small>context-driven</small></div></div><div class="workspace-grid"><section class="stack"><div class="card"><div class="card-title"><div><div class="eyebrow">SIGN-IN TELEMETRY</div><h2>Event Timeline</h2></div></div><div class="toolbar"><input id="ztSearch" class="input" style="max-width:280px" placeholder="Search user, IP, device..." value="${esc(ztFilter.q)}"><select id="ztResultFilter" class="input" style="max-width:150px"><option value="all">All results</option><option value="success" ${ztFilter.result==='success'?'selected':''}>Success</option><option value="failure" ${ztFilter.result==='failure'?'selected':''}>Failure</option></select><select id="ztCountryFilter" class="input" style="max-width:180px"><option value="all">All countries</option>${countries.map(c=>`<option ${ztFilter.country===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div><div class="data-table-wrap"><table class="data-table"><thead><tr><th>Time</th><th>User</th><th>IP</th><th>Country</th><th>Device</th><th>App</th><th>Result</th><th>MFA</th><th>Risk</th></tr></thead><tbody>${rows.map(r=>{const idx=all.indexOf(r);return `<tr data-zt-row="${idx}" class="${idx===selectedZT?'selected':''}"><td>${fmt(r.TimeGenerated)}</td><td><span class="table-link">${esc(r.UserPrincipalName)}</span></td><td>${esc(r.IPAddress)}</td><td>${esc(r.Country)}</td><td>${esc(r.Device)}</td><td>${esc(r.AppDisplayName)}</td><td>${r.Result==='Success'?'<span class="badge success">SUCCESS</span>':'<span class="badge danger">FAILURE</span>'}</td><td>${boolBadge(r.MFAUsed)}</td><td>${riskBadge(r.RiskLevel)}</td></tr>`}).join('')}</tbody></table></div></div><div class="card"><div class="card-title"><div><div class="eyebrow">INVESTIGATION</div><h2>Zero Trust Decision</h2></div></div><div class="check-list">${[['verify','Verify identity, IP, location and device context.'],['mfa','Determine whether MFA was required and used.'],['breach','Assume breach: inspect activity after the successful sign-in.'],['contain','Choose a containment action supported by evidence.']].map(([k,t])=>`<label class="check-row"><input type="checkbox" data-zt-task="${k}" ${tasks[k]?'checked':''}><span>${esc(t)}</span></label>`).join('')}</div><textarea class="input" id="ztNotes" placeholder="Analyst decision and rationale..." style="margin-top:12px">${esc(S.get().zeroTrust.notes)}</textarea><div class="toolbar"><button class="btn primary" id="saveZTDecisionBtn">SAVE DECISION</button><button class="btn" id="revealZTFindingBtn">REVEAL EXPECTED FINDING</button></div></div></section><aside class="stack"><div class="card"><div class="card-title"><div><div class="eyebrow">SELECTED EVENT</div><h2>${esc(selected.UserPrincipalName)}</h2></div>${riskBadge(selected.RiskLevel)}</div><div class="detail-list">${[['Time',fmt(selected.TimeGenerated)],['IP',selected.IPAddress],['Location',`${selected.City}, ${selected.Country}`],['Device',selected.Device],['App',selected.AppDisplayName],['Result',selected.Result],['MFA',selected.MFAUsed?'Used':'Not used'],['Session',selected.SessionId]].map(x=>`<div class="detail-row"><span>${x[0]}</span><b>${esc(x[1])}</b></div>`).join('')}</div><div class="toolbar"><button class="btn danger small" data-zt-action="contain">REVOKE SESSION</button><button class="btn small" data-zt-action="mfa">REQUIRE MFA</button><button class="btn small" data-zt-action="contact">CONTACT USER</button></div></div><div class="card"><div class="eyebrow">ATTACK CHAIN</div><h3 style="margin:8px 0">admin@example.com</h3><div class="timeline"><div class="timeline-item"><time>16:41–16:42</time><b>Repeated authentication failures</b><p>Same unfamiliar Russian IP and unknown device.</p></div><div class="timeline-item"><time>16:43</time><b>Successful Azure Portal sign-in</b><p>No MFA recorded, high risk context.</p></div><div class="timeline-item"><time>16:45</time><b>Global Administrator assignment</b><p>AuditLogs shows privileged directory change.</p></div><div class="timeline-item"><time>16:49</time><b>NSG management port exposed</b><p>AzureActivity shows TCP/22 opened from Internet.</p></div></div></div></aside></div>`;
    markModule('zero-trust');
  }
  function saveZT(){const notes=$('#ztNotes')?.value.trim()||'';const tasks=S.get().zeroTrust.tasks;const complete=['verify','mfa','breach','contain'].every(k=>tasks[k])&&notes.length>25;S.patch(s=>{s.zeroTrust.notes=notes;s.zeroTrust.completed=complete;});if(complete){S.addXP(110,'Zero Trust investigation completed');bumpSkill('ZeroTrust',7);bumpSkill('IncidentResponse',3);addCase('CASE-ZT','Suspicious Sign-in Investigation','Correlated failed and successful sign-ins, device/location/MFA context, post-login privilege change and resource activity before containment.','Zero Trust / SOC');toast('Investigation complete','Zero Trust case added to the casebook.','success');}else toast('Decision saved','Complete the checklist and provide a short rationale to finish the lab.');renderZeroTrust();}
  function ztAction(type){const ev=ztRows()[selectedZT]||ztRows()[4];S.patch(s=>s.zeroTrust.actions.push({type,session:ev.SessionId,time:new Date().toISOString()}));S.addAction(`Zero Trust action: ${type} for ${ev.UserPrincipalName}.`);toast('Response simulated',`${type} recorded for ${ev.SessionId}.`,'success');}
  function simulateSignal(){const n=S.get().zeroTrust.extraSignals.length+1;const e={TimeGenerated:new Date().toISOString(),UserPrincipalName:n%2?'max@contoso.com':'sarah@contoso.com',IPAddress:`203.0.113.${30+n}`,Country:n%2?'Netherlands':'Germany',City:n%2?'Amsterdam':'Berlin',Device:'Unknown Browser',AppDisplayName:'Azure Portal',ResultType:n%3===0?0:50126,Result:n%3===0?'Success':'Failure',MFAUsed:n%3===0,RiskLevel:n%2?'medium':'low',SessionId:`SIM-${100+n}`};S.patch(s=>s.zeroTrust.extraSignals.push(e));S.addAction('Synthetic sign-in signal generated.');toast('New telemetry generated',`${e.Result} from ${e.Country}.`);renderZeroTrust();}

  // DETECTION WORKBENCH
  function getDet(){return D.detections.find(d=>d.id===selectedDetection)||D.detections[0];}
  function renderDetections(){const det=getDet();const s=S.get();
    $('#detectionContent').innerHTML=`<div class="detection-layout"><aside class="detection-catalog"><div class="eyebrow" style="padding:4px 4px 8px">DETECTION CATALOG</div>${D.detections.map(d=>`<div class="detection-item ${d.id===det.id?'active':''}" data-detection-id="${d.id}"><b>${esc(d.name)}</b><span>${esc(d.source)} · ${d.severity.toUpperCase()} · ${esc(d.mitre)}</span></div>`).join('')}</aside><section class="workbench"><div class="editor-shell"><div class="editor-head"><span>workbench.kql // local runtime</span><div class="editor-actions"><button class="btn small" id="formatQueryBtn">FORMAT</button><button class="btn small" id="copyQueryBtn">COPY</button><button class="btn primary small" id="runQueryInlineBtn">RUN</button></div></div><textarea id="kqlEditor" class="code-editor" spellcheck="false">${esc(det.query)}</textarea></div><div class="card query-output"><div class="results-meta"><div><div class="eyebrow">QUERY RESULTS</div><h3 style="margin:5px 0">${lastKqlResult?lastKqlResult.count+' rows':'Run the query'}</h3></div><div class="toolbar"><button class="btn small" id="saveDetectionBtn">SAVE RULE</button><button class="btn danger small" id="createAlertBtn" ${!lastKqlResult||!lastKqlResult.count?'disabled':''}>CREATE ALERT</button></div></div>${renderKqlResults(lastKqlResult)}</div><div class="card"><div class="card-title"><div><div class="eyebrow">QUERY EXPLAINER</div><h3>Pipeline steps</h3></div></div><div id="queryExplain" class="query-explain">${K.explain($('#kqlEditor')?.value||det.query).map((x,i)=>`<div class="explain-step"><i>${i+1}</i><div><b>${esc(x.title)}</b><p>${esc(x.body)}</p></div></div>`).join('')}</div></div></section><aside class="stack"><div class="card"><div class="card-title"><div><div class="eyebrow">DETECTION CONTEXT</div><h2>${esc(det.name)}</h2></div>${riskBadge(det.severity)}</div><div class="detail-list"><div class="detail-row"><span>Log Source</span><b>${esc(det.source)}</b></div><div class="detail-row"><span>MITRE</span><b>${esc(det.mitre)} · ${esc(det.technique)}</b></div><div class="detail-row"><span>Mode</span><b>Local synthetic data</b></div></div><p>${esc(det.description)}</p><div class="callout"><strong>Use case:</strong> ${esc(det.useCase)}</div></div><div class="card"><div class="card-title"><div><div class="eyebrow">RULE LIBRARY</div><h3>Saved detections</h3></div><span class="micro-badge">${s.detections.saved.length}</span></div>${s.detections.saved.slice(0,5).map(r=>`<div class="callout" style="margin-top:7px"><strong>${esc(r.name)}</strong><br>${fmt(r.time)}</div>`).join('')||'<div class="micro-copy">No local rules saved yet.</div>'}</div></aside></div>`;
    markModule('detections');
  }
  function renderKqlResults(res){if(!res)return '<div class="micro-copy">Results will appear here. Supported local operations: where, project, summarize count() by, order by, take and flattened mv-expand.</div>';if(res.error)return `<div class="callout"><strong>Query error:</strong> ${esc(res.error)}</div>`;if(!res.rows.length)return '<div class="callout amber"><strong>No matching events.</strong> The query executed successfully.</div>';const cols=[...new Set(res.rows.flatMap(r=>Object.keys(r)))];return `<div class="data-table-wrap"><table class="data-table"><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${res.rows.slice(0,50).map(r=>`<tr>${cols.map(c=>`<td>${typeof r[c]==='boolean'?boolBadge(r[c]):esc(r[c])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
  function runKql(){const query=$('#kqlEditor')?.value||getDet().query;try{lastKqlResult=K.run(query,{SigninLogs:ztRows(),AuditLogs:D.auditLogs,AzureActivity:D.azureActivity});S.patch(s=>s.detections.runs.unshift({time:new Date().toISOString(),detection:selectedDetection,query,count:lastKqlResult.count}));S.addXP(15,'Local KQL query executed');bumpSkill('KQL',1);toast('Query complete',`${lastKqlResult.count} rows returned.`,'success');}catch(e){lastKqlResult={error:e.message,rows:[],count:0};toast('Query error',e.message,'warn');}renderDetections();}
  function saveDetection(){const d=getDet(),query=$('#kqlEditor')?.value||d.query;S.patch(s=>s.detections.saved.unshift({id:`R-${Date.now()}`,name:d.name,source:d.source,severity:d.severity,query,time:new Date().toISOString()}));S.addXP(25,'Detection rule saved');bumpSkill('Detection',2);toast('Rule saved',`${d.name} added to local rule library.`,'success');renderDetections();}
  function createAlert(){if(!lastKqlResult?.count)return;const d=getDet();const alert={id:`ALT-${Date.now().toString().slice(-6)}`,name:d.name,severity:d.severity,created:new Date().toISOString(),count:lastKqlResult.count,source:d.source,status:'New'};S.patch(s=>s.detections.alerts.unshift(alert));S.addAction(`Alert generated: ${d.name} (${lastKqlResult.count} hits).`);S.addXP(20,'Detection hit converted to alert');toast('Alert generated',`${d.name} · ${lastKqlResult.count} hits.`,'success');}

  // INCIDENTS
  function renderIncidents(){const incidents=S.get().incidents;let inc=incidents.find(i=>i.id===selectedIncident)||incidents[0];if(!inc){$('#incidentContent').innerHTML='<div class="card">No incidents.</div>';return;}selectedIncident=inc.id;
    $('#incidentContent').innerHTML=`<div class="stat-strip"><div class="stat-box"><span>ACTIVE</span><b>${incidents.filter(i=>!['Resolved','Closed'].includes(i.status)).length}</b><small>open investigations</small></div><div class="stat-box"><span>CRITICAL</span><b>${incidents.filter(i=>i.severity==='critical'&&i.status!=='Resolved').length}</b><small>priority queue</small></div><div class="stat-box"><span>RESOLVED</span><b>${incidents.filter(i=>i.status==='Resolved').length}</b><small>contained and documented</small></div><div class="stat-box"><span>ALERTS</span><b>${S.get().detections.alerts.length}</b><small>generated locally</small></div></div><div class="incident-layout"><aside class="card"><div class="card-title"><div><div class="eyebrow">INCIDENT QUEUE</div><h2>Cases</h2></div></div><div class="incident-list">${incidents.map(i=>`<div class="incident-card ${i.id===inc.id?'active':''}" data-incident-id="${i.id}"><div class="incident-card-head"><span class="micro-copy">${i.id}</span>${riskBadge(i.severity)}</div><h3>${esc(i.title)}</h3><p>${esc(i.entity)} · ${esc(i.status)}</p></div>`).join('')}</div></aside><section class="stack"><div class="card"><div class="card-title"><div><div class="eyebrow">${esc(inc.id)} // ${esc(inc.status.toUpperCase())}</div><h2>${esc(inc.title)}</h2></div>${riskBadge(inc.severity)}</div><p>${esc(inc.summary)}</p><div class="stat-strip"><div class="stat-box"><span>ENTITY</span><b style="font-size:15px">${esc(inc.entity)}</b><small>primary account/resource</small></div><div class="stat-box"><span>OWNER</span><b style="font-size:15px">${esc(inc.owner)}</b><small>analyst</small></div><div class="stat-box"><span>EVIDENCE</span><b>${inc.evidence.length}</b><small>artifacts</small></div><div class="stat-box"><span>ACTIONS</span><b>${inc.actions.length}</b><small>response steps</small></div></div><div class="toolbar"><button class="btn small" data-inc-action="assign">ASSIGN TO ME</button><button class="btn warn small" data-inc-action="investigate">MARK INVESTIGATING</button><button class="btn danger small" data-inc-action="contain">CONTAIN</button><button class="btn success small" data-inc-action="resolve">RESOLVE</button></div></div><div class="workspace-grid"><div class="card"><div class="card-title"><div><div class="eyebrow">ATTACK TIMELINE</div><h3>Observed activity</h3></div></div><div class="timeline">${inc.timeline.map(t=>`<div class="timeline-item"><time>${esc(t.time)}</time><b>${esc(t.title)}</b><p>${esc(t.detail)}</p></div>`).join('')}</div></div><div class="card"><div class="card-title"><div><div class="eyebrow">EVIDENCE</div><h3>Artifacts</h3></div></div>${inc.evidence.map(e=>`<div class="callout" style="margin-top:7px">${esc(e)}</div>`).join('')}</div></div><div class="card"><div class="card-title"><div><div class="eyebrow">ANALYST NOTES</div><h3>Investigation log</h3></div></div><textarea id="incidentNote" class="input" placeholder="Document evidence, hypothesis, containment and next steps..."></textarea><div class="toolbar"><button class="btn primary small" id="addIncidentNoteBtn">ADD NOTE</button></div>${inc.notes.map(n=>`<div class="callout" style="margin-top:8px"><strong>${fmt(n.time)}</strong><br>${esc(n.text)}</div>`).join('')}</div></section></div>`;markModule('incidents');}
  function incidentAction(type){const id=selectedIncident;S.patch(s=>{const i=s.incidents.find(x=>x.id===id);if(!i)return;if(type==='assign')i.owner='Jannik';if(type==='investigate')i.status='Investigating';if(type==='contain'){i.status='Contained';i.actions.push({time:new Date().toISOString(),type:'Session / access containment simulated'});}if(type==='resolve'){i.status='Resolved';i.actions.push({time:new Date().toISOString(),type:'Incident resolved after evidence review'});}});if(type==='resolve'){S.addXP(120,'Incident resolved');bumpSkill('IncidentResponse',7);const i=S.get().incidents.find(x=>x.id===id);addCase(`CASE-${id}`,i.title,`${i.summary} Response actions and investigation notes were documented in the local incident workflow.`,'SOC / Incident Response');}else S.addXP(15,`Incident action: ${type}`);toast('Incident updated',`${id} → ${type}.`,'success');renderIncidents();}
  function addIncidentNote(){const t=$('#incidentNote')?.value.trim();if(!t)return;S.patch(s=>{const i=s.incidents.find(x=>x.id===selectedIncident);if(i)i.notes.unshift({time:new Date().toISOString(),text:t});});S.addAction(`Analyst note added to ${selectedIncident}.`);toast('Note saved');renderIncidents();}
  function seedIncident(){const n=S.get().incidents.length+1;const id=`INC-24${String(n).padStart(2,'0')}`;S.patch(s=>s.incidents.unshift({id,title:'Synthetic password spray investigation',severity:'high',status:'New',owner:'Unassigned',created:new Date().toISOString(),entity:'203.0.113.77',summary:'Synthetic source generated repeated failed sign-ins across multiple accounts.',evidence:['Source IP: 203.0.113.77','Multiple user accounts targeted','ResultType indicates failures'],timeline:[{time:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}),title:'Detection hit generated',detail:'Password spray pattern created by local scenario generator.'}],notes:[],actions:[]}));selectedIncident=id;S.addAction(`Synthetic incident generated: ${id}.`);renderIncidents();toast('Scenario generated',id);}

  // POSTURE
  function secureScore(){return Math.max(0,100-S.get().posture.findings.filter(f=>!f.remediated).reduce((a,b)=>a+b.points,0));}
  function renderPosture(){const f=S.get().posture.findings,score=secureScore();$('#postureContent').innerHTML=`<div class="posture-top"><div class="card" style="display:grid;place-items:center"><div class="score-ring" style="--score-angle:${score*3.6}deg"><div class="score-value"><b>${score}</b><span>SECURE SCORE / 100</span></div></div><div class="micro-copy" style="margin-top:14px">Local scoring model · educational simulation</div></div><div class="card"><div class="stat-strip"><div class="stat-box"><span>ACTIVE FINDINGS</span><b>${f.filter(x=>!x.remediated).length}</b><small>configuration risks</small></div><div class="stat-box"><span>CRITICAL / HIGH</span><b>${f.filter(x=>!x.remediated&&['critical','high'].includes(x.severity)).length}</b><small>prioritize first</small></div><div class="stat-box"><span>REMEDIATED</span><b>${f.filter(x=>x.remediated).length}</b><small>local fixes</small></div><div class="stat-box"><span>RESOURCES</span><b>${D.postureResources.length}</b><small>synthetic Azure estate</small></div></div><div class="callout ${score>=80?'green':score>=60?'amber':''}"><strong>Posture guidance:</strong> Prioritize broad internet exposure and anonymous data access before lower-impact hardening recommendations.</div></div></div><div class="card" style="margin-top:14px"><div class="card-title"><div><div class="eyebrow">SECURITY RECOMMENDATIONS</div><h2>Findings</h2></div></div><div class="finding-list">${f.sort((a,b)=>sevRank[b.severity]-sevRank[a.severity]).map(x=>`<div class="finding ${x.remediated?'remediated':''}"><div>${x.remediated?'<span class="badge success">FIXED</span>':riskBadge(x.severity)}</div><div><h3>${esc(x.title)}</h3><p>${esc(x.recommendation)}</p></div><div><div class="resource">${esc(x.resource)} · ${esc(x.category)}</div><button class="btn small ${x.remediated?'success':'primary'}" data-posture-fix="${x.id}" ${x.remediated?'disabled':''} style="margin-top:7px">${x.remediated?'REMEDIATED':'REMEDIATE'}</button></div></div>`).join('')}</div></div>`;markModule('posture');}
  function fixPosture(id){S.patch(s=>{const f=s.posture.findings.find(x=>x.id===id);if(f)f.remediated=true;});S.addXP(35,'Cloud posture finding remediated');bumpSkill('Azure',2);toast('Finding remediated',`${id} fixed in local state.`,'success');renderPosture();}

  // IAC
  function renderIaC(){const s=S.get();const code=iacTab==='main'?D.iac.main:D.iac.network;const scans=s.iac.lastScan||[];$('#iacContent').innerHTML=`<div class="iac-layout"><section class="stack"><div class="card"><div class="card-title"><div><div class="eyebrow">SOURCE</div><h2>Bicep Workspace</h2></div><div class="toolbar"><button class="btn small ${iacTab==='main'?'primary':''}" data-iac-tab="main">main.bicep</button><button class="btn small ${iacTab==='network'?'primary':''}" data-iac-tab="network">modules/network.bicep</button></div></div><pre class="code-block">${esc(code)}</pre></div><div class="card"><div class="card-title"><div><div class="eyebrow">STATIC SCAN</div><h2>Security Checks</h2></div><span class="micro-badge">${s.iac.scanRuns} RUNS</span></div><div class="scan-results">${scans.length?scans.map(x=>`<div class="scan-item ${x.status==='warn'?'warn':''}"><span class="scan-icon">${x.status==='pass'?'✓':'!'}</span><div><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p></div></div>`).join(''):'<div class="micro-copy">Run the local security scan to evaluate the template.</div>'}</div></div></section><aside class="stack"><div class="card"><div class="eyebrow">ARCHITECTURE</div><h3 style="margin:8px 0 14px">Segmented VNet</h3><div class="arch-diagram"><div class="arch-node">Internet</div><div class="arch-arrow">↓ HTTPS :443</div><div class="arch-node">web-subnet 10.0.1.0/24<br>nsg-web</div><div class="arch-arrow">↓ SQL :1433</div><div class="arch-node">db-subnet 10.0.2.0/24<br>nsg-db</div></div></div><div class="card"><div class="eyebrow">SECURITY RATIONALE</div><h3 style="margin:8px 0">No deployment required</h3><div class="callout green"><strong>Good:</strong> The database subnet is not directly exposed to the Internet. Only the web subnet is allowed to reach TCP/1433.</div><div class="callout" style="margin-top:8px"><strong>Remember:</strong> Separate subnets do not automatically block traffic. NSG rules provide the explicit filtering in this lab design.</div></div></aside></div>`;markModule('iac');}
  function runIaCScan(){const checks=[{status:'pass',title:'Web ingress is restricted to HTTPS',detail:'Internet source is limited to TCP/443 on nsg-web.'},{status:'pass',title:'Database is not internet-exposed',detail:'nsg-db accepts TCP/1433 only from 10.0.1.0/24.'},{status:'pass',title:'Network segmentation present',detail:'Web and DB tiers use separate /24 subnets.'},{status:'pass',title:'NSGs referenced by resource ID',detail:'Subnet networkSecurityGroup properties use webNsg.id and dbNsg.id.'},{status:'warn',title:'Production hardening not modeled',detail:'This learning template does not include DDoS, private endpoints, centralized firewalling or diagnostics.'}];S.patch(s=>{s.iac.scanRuns++;s.iac.lastScan=checks;});S.addXP(60,'Bicep security scan completed');bumpSkill('IaC',5);addCase('CASE-IAC','Bicep Network Security Review','Reviewed a segmented Azure VNet design with web and DB subnets, NSGs, least-privilege ports and local static security checks.','Infrastructure as Code');toast('Scan complete','4 checks passed · 1 scope warning.','success');renderIaC();}

  // PORTFOLIO
  function addCase(id,title,summary,area){S.patch(s=>{if(!s.casebook.some(c=>c.id===id))s.casebook.unshift({id,title,summary,area,time:new Date().toISOString()});});}
  function renderPortfolio(){const s=S.get();const defaults=[{id:'CASE-BASELINE',title:'Cloud Security Fundamentals Lab v5.0',summary:'Local-first cloud security training platform combining identity, Zero Trust, KQL, detection engineering, incident response, posture and IaC review.',area:'Project Engineering',time:'2026-09-09T00:00:00Z'}];const cases=[...s.casebook,...defaults.filter(d=>!s.casebook.some(c=>c.id===d.id))];const achievements=[['firstQuery','QUERY RUNNER','Executed a local KQL query.','⌁'],['accessReviewer','ACCESS REVIEWER','Completed Identity & Access review.','◈'],['zeroTrustAnalyst','ZERO TRUST ANALYST','Completed sign-in investigation.','◎'],['detector','DETECTION BUILDER','Saved two detection rules.','⌗'],['responder','INCIDENT RESPONDER','Resolved a security incident.','⚑'],['postureEngineer','POSTURE ENGINEER','Remediated three posture findings.','◇'],['iacReviewer','IAC REVIEWER','Ran the Bicep security scan.','⌂'],['caseWriter','CASE WRITER','Created a portfolio case.','✎']];$('#portfolioContent').innerHTML=`<div class="stat-strip"><div class="stat-box"><span>CASE STUDIES</span><b>${cases.length}</b><small>exportable evidence</small></div><div class="stat-box"><span>ACHIEVEMENTS</span><b>${achievements.filter(a=>s.achievements[a[0]]).length}/${achievements.length}</b><small>local milestones</small></div><div class="stat-box"><span>LEVEL</span><b>${s.level}</b><small>${s.xp} XP</small></div><div class="stat-box"><span>PROJECT MODE</span><b style="font-size:17px">LOCAL</b><small>no paid Azure resources</small></div></div><div class="card"><div class="card-title"><div><div class="eyebrow">CASEBOOK</div><h2>Security Evidence</h2></div></div><div class="case-grid">${cases.map(c=>`<article class="case-card"><span class="case-id">${esc(c.id)} // ${esc(c.area.toUpperCase())}</span><h3>${esc(c.title)}</h3><p>${esc(c.summary)}</p><footer><span>${fmt(c.time)}</span><b>PORTFOLIO READY</b></footer></article>`).join('')}</div></div><div class="card" style="margin-top:14px"><div class="card-title"><div><div class="eyebrow">ACHIEVEMENTS</div><h2>Capability Milestones</h2></div></div><div class="achievement-grid">${achievements.map(a=>`<div class="achievement ${s.achievements[a[0]]?'unlocked':''}"><div class="icon">${a[3]}</div><b>${a[1]}</b><span>${a[2]}</span></div>`).join('')}</div></div>`;markModule('portfolio');}
  function casebookMarkdown(){const s=S.get();return `# Cloud Security Fundamentals Lab — Portfolio Casebook\n\nGenerated locally from v5.0.\n\n## Project\n\n**Cloud Security Fundamentals Lab v5.0** is a local-first training platform for Azure security, Microsoft Entra ID, Zero Trust, KQL, detection engineering, incident response, cloud posture and Bicep review. No paid cloud resources are required.\n\n## Evidence Cases\n\n${s.casebook.map(c=>`### ${c.title}\n\n- Area: ${c.area}\n- Completed: ${c.time}\n- Summary: ${c.summary}\n`).join('\n')||'No completed cases yet. Finish investigations in the lab to populate this section.\n'}\n## Capability Snapshot\n\n${Object.entries(s.skills).map(([k,v])=>`- ${k}: ${v}%`).join('\n')}\n\n## Notes\n\nThese are synthetic learning scenarios and local simulations, not production incident records.\n`;}

  // COMMANDS / EXPORT / RESET
  const commands=[
    ['Command Dashboard','dashboard','Open mission control'],['Certification Training','learn','Practice AZ-900 / SC-900'],['Identity & Access Review','identity','Review roles and scope'],['Zero Trust Investigation','zero-trust','Investigate risky sign-ins'],['Detection Workbench','detections','Run local KQL'],['Incident Response Center','incidents','Triage and resolve cases'],['Cloud Security Posture','posture','Review findings'],['Bicep Security Review','iac','Inspect IaC'],['Portfolio Casebook','portfolio','Export evidence']
  ];
  function openPalette(){const p=$('#commandPalette');p.classList.remove('hidden');p.setAttribute('aria-hidden','false');$('#commandSearch').value='';renderCommands('');setTimeout(()=>$('#commandSearch').focus(),20)}
  function closePalette(){const p=$('#commandPalette');p.classList.add('hidden');p.setAttribute('aria-hidden','true')}
  function renderCommands(q){const v=q.toLowerCase();$('#commandResults').innerHTML=commands.filter(c=>c.join(' ').toLowerCase().includes(v)).map(c=>`<div class="command-item" data-command-view="${c[1]}"><div><b>${c[0]}</b><span style="display:block;margin-top:3px">${c[2]}</span></div><span>OPEN →</span></div>`).join('')||'<div class="micro-copy" style="padding:12px">No command matches.</div>';}
  function exportProgress(){download('cloud-security-fundamentals-lab-v5-state.json',S.exportState(),'application/json');toast('State exported','Local progress downloaded as JSON.','success');}
  function resetPrompt(){modal('Reset all local progress?','<p>This clears quiz history, analyst notes, simulated remediations, incidents, posture fixes, XP and achievements. Source datasets remain unchanged.</p>','<button class="btn" data-modal-close>CANCEL</button><button class="btn danger" id="confirmResetBtn">RESET EVERYTHING</button>')}
  function resetAll(){S.reset();lastKqlResult=null;selectedIdentity=4;selectedZT=4;selectedDetection='failed-logins';selectedIncident='INC-2401';closeModal();toast('Progress reset','v5.0 returned to its clean local state.','warn');render(S.get().lastView||'dashboard');}

  function expectedIdentity(){modal('Expected Identity Finding','<div class="callout"><strong>Primary critical finding:</strong> Tom Weber is a Helpdesk Technician with permanent Microsoft Entra Global Administrator at Tenant scope, MFA disabled and ExpectedAccess=false.</div><p>Additional high-risk examples include service-backup with subscription Owner and Sarah Frey with unexpected subscription Owner. Context matters: Jannik’s Owner assignment is expected and scoped only to the security lab resource group.</p>');}
  function expectedZT(){modal('Expected Zero Trust Finding','<div class="callout"><strong>High-confidence suspicious chain:</strong> admin@example.com has repeated failures from Russia on an unknown device, followed by a successful Azure Portal sign-in without MFA. AuditLogs then shows a Global Administrator assignment and AzureActivity shows an Internet-facing SSH rule change.</div><p>Recommended workflow: verify user context, revoke the suspicious session, secure credentials/authentication, review post-login changes, remove unauthorized privilege and investigate persistence.</p>');}

  // EVENT DELEGATION
  document.addEventListener('click',e=>{
    const nav=e.target.closest('[data-action="navigate"]');if(nav){navigate(nav.dataset.view);return;}
    if(e.target.closest('[data-modal-close]')){closeModal();return;}
    const qs=e.target.closest('[data-quiz-start]');if(qs){startQuiz(qs.dataset.quizStart,qs.dataset.mode);return;}
    const ans=e.target.closest('[data-answer]');if(ans){answerQuiz(Number(ans.dataset.answer));return;}
    if(e.target.closest('[data-quiz-next]')){nextQuiz();return;}if(e.target.closest('[data-quiz-exit]')||e.target.closest('[data-quiz-home]')){renderLearnHome();return;}if(e.target.closest('[data-drawer-close]')){$('#learnDrawer').classList.add('hidden');return;}
    const ir=e.target.closest('[data-identity-row]');if(ir){selectedIdentity=Number(ir.dataset.identityRow);renderIdentity();return;}
    const rem=e.target.closest('[data-id-remediate]');if(rem){remediateIdentity(rem.dataset.idRemediate);return;}
    const zr=e.target.closest('[data-zt-row]');if(zr){selectedZT=Number(zr.dataset.ztRow);renderZeroTrust();return;}
    const za=e.target.closest('[data-zt-action]');if(za){ztAction(za.dataset.ztAction);return;}
    const di=e.target.closest('[data-detection-id]');if(di){selectedDetection=di.dataset.detectionId;lastKqlResult=null;renderDetections();return;}
    const ii=e.target.closest('[data-incident-id]');if(ii){selectedIncident=ii.dataset.incidentId;renderIncidents();return;}
    const ia=e.target.closest('[data-inc-action]');if(ia){incidentAction(ia.dataset.incAction);return;}
    const pf=e.target.closest('[data-posture-fix]');if(pf){fixPosture(pf.dataset.postureFix);return;}
    const it=e.target.closest('[data-iac-tab]');if(it){iacTab=it.dataset.iacTab;renderIaC();return;}
    const cmd=e.target.closest('[data-command-view]');if(cmd){closePalette();navigate(cmd.dataset.commandView);return;}

    if(e.target.id==='showHistoryBtn')showLearnDrawer('history');
    else if(e.target.id==='showWeakAreasBtn')showLearnDrawer('weak');
    else if(e.target.id==='runAccessReviewBtn'){selectedIdentity=4;renderIdentity();toast('Access review ready','Critical and unexpected access can now be investigated.');}
    else if(e.target.id==='resetIdentityBtn'){S.patch(s=>s.identity={notes:'',tasks:{},remediations:[],completed:false});renderIdentity();}
    else if(e.target.id==='saveIdentityDecisionBtn')saveIdentityReview();
    else if(e.target.id==='revealIdentityFindingBtn')expectedIdentity();
    else if(e.target.id==='simulateSignInBtn')simulateSignal();
    else if(e.target.id==='resetZeroTrustBtn'){S.patch(s=>s.zeroTrust={notes:'',tasks:{},actions:[],completed:false,extraSignals:[]});renderZeroTrust();}
    else if(e.target.id==='saveZTDecisionBtn')saveZT();
    else if(e.target.id==='revealZTFindingBtn')expectedZT();
    else if(e.target.id==='runKqlBtn'||e.target.id==='runQueryInlineBtn')runKql();
    else if(e.target.id==='loadDefaultDetectionBtn'){lastKqlResult=null;renderDetections();}
    else if(e.target.id==='formatQueryBtn'){const ed=$('#kqlEditor');if(ed)ed.value=ed.value.split('\n').map(x=>x.trim()).join('\n');}
    else if(e.target.id==='copyQueryBtn'){navigator.clipboard?.writeText($('#kqlEditor')?.value||'');toast('Query copied');}
    else if(e.target.id==='saveDetectionBtn')saveDetection();
    else if(e.target.id==='createAlertBtn')createAlert();
    else if(e.target.id==='seedIncidentBtn')seedIncident();
    else if(e.target.id==='addIncidentNoteBtn')addIncidentNote();
    else if(e.target.id==='resetPostureBtn'){S.patch(s=>s.posture.findings=JSON.parse(JSON.stringify(D.postureFindings)));renderPosture();}
    else if(e.target.id==='runIaCScanBtn')runIaCScan();
    else if(e.target.id==='exportCasebookBtn')download('Cloud-Security-Lab-v5-Casebook.md',casebookMarkdown(),'text/markdown');
    else if(e.target.id==='exportStateBtn'||e.target.id==='exportBtn')exportProgress();
    else if(e.target.id==='resetProgressBtn')resetPrompt();
    else if(e.target.id==='confirmResetBtn')resetAll();
    else if(e.target.id==='commandBtn')openPalette();
  });
  document.addEventListener('change',e=>{
    if(e.target.matches('[data-identity-task]')){S.patch(s=>s.identity.tasks[e.target.dataset.identityTask]=e.target.checked);}
    if(e.target.matches('[data-zt-task]')){S.patch(s=>s.zeroTrust.tasks[e.target.dataset.ztTask]=e.target.checked);}
    if(e.target.id==='identityRiskFilter'){idFilter.risk=e.target.value;renderIdentity();}
    if(e.target.id==='ztResultFilter'){ztFilter.result=e.target.value;renderZeroTrust();}
    if(e.target.id==='ztCountryFilter'){ztFilter.country=e.target.value;renderZeroTrust();}
  });
  document.addEventListener('input',e=>{
    if(e.target.id==='identitySearch'){idFilter.q=e.target.value;renderIdentity();setTimeout(()=>$('#identitySearch')?.focus(),0);}
    if(e.target.id==='ztSearch'){ztFilter.q=e.target.value;renderZeroTrust();setTimeout(()=>$('#ztSearch')?.focus(),0);}
    if(e.target.id==='identityNotes')S.patch(s=>s.identity.notes=e.target.value);
    if(e.target.id==='ztNotes')S.patch(s=>s.zeroTrust.notes=e.target.value);
    if(e.target.id==='commandSearch')renderCommands(e.target.value);
    if(e.target.id==='kqlEditor'){$('#queryExplain').innerHTML=K.explain(e.target.value).map((x,i)=>`<div class="explain-step"><i>${i+1}</i><div><b>${esc(x.title)}</b><p>${esc(x.body)}</p></div></div>`).join('');}
  });
  document.addEventListener('keydown',e=>{
    if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openPalette();}
    if(e.key==='Escape'){closePalette();closeModal();}
    if(e.target.classList.contains('brand')&&(e.key==='Enter'||e.key===' '))navigate('dashboard');
  });
  $('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal();});
  $('#commandPalette').addEventListener('click',e=>{if(e.target.id==='commandPalette')closePalette();});

  S.recompute(); S.save(); const initial=S.get().lastView||'dashboard'; navigate(initial);
})();
